const input = $input.first().json;
const timezone = 'America/Bogota';
const periodEnd = new Date();
const localParts = Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(periodEnd)
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value])
);
const periodStartDate = `${localParts.year}-${localParts.month}-01`;
const periodEndDate = `${localParts.year}-${localParts.month}-${localParts.day}`;
const periodStart = new Date(`${periodStartDate}T00:00:00-05:00`);
const periodDaysElapsed = Number(localParts.day);
const formatPeriodDate = (date) => new Intl.DateTimeFormat('es-CO', {
  timeZone: 'UTC',
  day: 'numeric',
  month: 'long',
  year: 'numeric'
}).format(new Date(`${date}T12:00:00Z`));
const periodLabel = `${formatPeriodDate(periodStartDate)} al ${formatPeriodDate(periodEndDate)}`;
const reportingContract = {
  version: '1.0',
  mode: 'MONTH_TO_DATE',
  cadenceDays: 7,
  timezone,
  periodStartDate,
  periodEndDate,
  periodStart: periodStart.toISOString(),
  periodEnd: periodEnd.toISOString(),
  daysElapsed: periodDaysElapsed,
  accumulationStrategy: 'SOURCE_REQUERY_NO_ROLLUP'
};
const clientConfig = {
  clientId: input.clientId || 'CLI-001',
  clientName: input.clientName || 'Proyecto Pekín',
  hubspotCompanyId: '<CONFIGURE_HUBSPOT_COMPANY_ID>',
  slidesTemplateId: '16SvDTUUF9q7VspDWbX8Zr4YTU6QJi__L3oh5qvJYtq0',
  driveFolderId: '<CONFIGURE_GOOGLE_DRIVE_FOLDER_ID>',
  periodLeadGoal: 100,
  periodInvestmentGoal: 5000000,
  timezone
};
return [{ json: {
  ...input,
  ...clientConfig,
  periodMode: reportingContract.mode,
  reportCadenceDays: reportingContract.cadenceDays,
  periodStartDate,
  periodEndDate,
  periodStart: reportingContract.periodStart,
  periodEnd: reportingContract.periodEnd,
  periodDaysElapsed,
  periodLabel,
  reportingContract
} }];

const input = $input.first().json;
const metrics = {
  recognition: { kpi: 125000, actual: 14014, performance: 11.21, budget: 500000, investment: 48732 },
  investors: { kpi: 120, leads: 62, performance: 51.67, budget: 1200000, investment: 288141, cpa: 5145 },
  housing: { kpi: 40, leads: 17, performance: 42.50, budget: 400000, investment: 97517, cpa: 5736 },
  studio: { investment: 95888, leads: 6, cpa: 15981 },
  pmax: { kpi: 30, leads: 24, performance: 80.00, budget: 1200000, investment: 381000 },
  totals: { targetLeads: 190, generatedLeads: 103, performance: 54.21, remainder: 2388801 },
  leadsRegistered: 103,
  mqls: 41,
  noNicho: 12,
  pendingClassification: 8,
  sales: 5,
  actualInvestment: 4650000
};
const leadAchievement = Number(((metrics.leadsRegistered / input.periodLeadGoal) * 100).toFixed(1));
const cpl = Math.round(metrics.actualInvestment / metrics.leadsRegistered);
return [{ json: { ...input, ...metrics, leadAchievement, cpl, dataSource: 'mock' } }];

const input = $input.first().json;
const metricsForAI = {
  project: input.clientName,
  reportingContract: input.reportingContract,
  periodLabel: input.periodLabel,
  periodLeadGoal: input.periodLeadGoal,
  periodInvestmentGoal: input.periodInvestmentGoal,
  recognition: input.recognition,
  investors: input.investors,
  housing: input.housing,
  studio: input.studio,
  pmax: input.pmax,
  totals: input.totals,
  crm: { leadsRegistered: input.leadsRegistered, mqls: input.mqls, noNicho: input.noNicho, pendingClassification: input.pendingClassification, sales: input.sales },
  leadAchievement: input.leadAchievement,
  cpl: input.cpl,
  actualInvestment: input.actualInvestment
};
const prompt = [
  'Actua como analista senior de performance de Tic Tac Agency.',
  'Analiza exclusivamente los datos suministrados. No inventes cifras, causas ni resultados.',
  'Todos los datos representan el acumulado del mes desde el dia 1 hasta el momento de generacion indicado en reportingContract.',
  'No describas los datos como ultimos 7 dias ni como una semana aislada. La revision ocurre cada 7 dias, pero el periodo siempre es MONTH_TO_DATE.',
  'Redacta en espanol ejecutivo de Colombia, claro, breve, formal, proactivo y orientado a decisiones.',
  'Cada texto debe tener entre 35 y 70 palabras y no debe usar Markdown.',
  'ANALISIS_TENDENCIA_VIVIENDA: explica los resultados principales, cumplimiento, eficiencia y tendencia acumulada del mes.',
  'RECOMENDACION_AGENCIA_VIVIENDA: propone acciones concretas y prudentes para el proximo corte acumulado.',
  'SINTESIS_EMBUDO: resume calidad y avance acumulado del embudo CRM, mencionando MQL, pendientes y ventas.',
  'Devuelve solamente el objeto JSON solicitado.',
  `DATOS DEL PERIODO:\n${JSON.stringify(metricsForAI)}`
].join('\n\n');
const geminiRequestBody = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.25,
    topP: 0.8,
    maxOutputTokens: 700,
    responseMimeType: 'application/json',
    responseJsonSchema: {
      type: 'object',
      additionalProperties: false,
      required: ['ANALISIS_TENDENCIA_VIVIENDA', 'RECOMENDACION_AGENCIA_VIVIENDA', 'SINTESIS_EMBUDO'],
      properties: {
        ANALISIS_TENDENCIA_VIVIENDA: { type: 'string' },
        RECOMENDACION_AGENCIA_VIVIENDA: { type: 'string' },
        SINTESIS_EMBUDO: { type: 'string' }
      }
    }
  }
};
return [{ json: { ...input, geminiRequestBody } }];

const source = $('Preparar Solicitud Gemini').first().json;
const response = $input.first().json;
const candidate = response.candidates?.[0];
const finishReason = candidate?.finishReason || 'UNKNOWN';
const text = candidate?.content?.parts?.map((part) => part.text || '').join('').trim();
if (!text) {
  const blockReason = response.promptFeedback?.blockReason || 'sin detalle';
  throw new Error(`Gemini no devolvio contenido. finishReason=${finishReason}; blockReason=${blockReason}`);
}
let strategicCopy;
try {
  strategicCopy = JSON.parse(text);
} catch (error) {
  throw new Error(`Gemini devolvio JSON invalido: ${error.message}`);
}
const required = ['ANALISIS_TENDENCIA_VIVIENDA', 'RECOMENDACION_AGENCIA_VIVIENDA', 'SINTESIS_EMBUDO'];
for (const field of required) {
  if (typeof strategicCopy[field] !== 'string' || !strategicCopy[field].trim()) {
    throw new Error(`Respuesta Gemini incompleta: falta ${field}`);
  }
  strategicCopy[field] = strategicCopy[field].trim();
}
const { geminiRequestBody, ...cleanSource } = source;
return [{ json: { ...cleanSource, strategicCopy, aiSource: 'gemini-3.5-flash', geminiUsage: response.usageMetadata || null } }];

const source = $('Preparar Placeholders de Slides').first().json;
const copy = $input.first().json;
if (!copy.id) throw new Error('Google Drive no devolvió el ID de la copia.');
const requests = Object.entries(source.replacements).map(([placeholder, value]) => ({
  replaceAllText: {
    containsText: { text: placeholder, matchCase: true },
    replaceText: String(value ?? '')
  }
}));
return [{ json: { ...source, presentationId: copy.id, copiedFileName: copy.name, batchUpdateBody: { requests } } }];

const prepared = $('Preparar Batch Update').first().json;
const slidesResponse = $input.first().json;
const reportUrl = `https://docs.google.com/presentation/d/${prepared.presentationId}/edit`;
return [{ json: { ...prepared, slidesResponse, reportStatus: 'slides_ready', reportUrl } }];

const input = $input.first().json;
const divider = '\u2501'.repeat(14);
const finalMessage = [
  '\u2705 *TIC TAC | INFORME COMPLETADO*',
  divider,
  `\u{1F3E2} *Proyecto:* ${input.clientName}`,
  `\u{1F4C5} *Periodo acumulado:* ${input.periodLabel}`,
  '\u{1F504} *Contrato:* Desde el día 1 hasta este corte',
  '\u{1F9E9} *HubSpot:* espacios listos para dashboards manuales',
  '',
  `\u{1F4C1} *Ver informe:* ${input.reportUrl}`,
  divider,
  '\u2139\uFE0F _Google Ads y Meta Ads: datos reales. HubSpot: inserción manual._',
  '_Tic Tac Agency Performance SAS_'
].join('\n');
return [{ json: { ...input, finalMessage } }];

const base = $('Incorporar Meta Ads Real').first().json;
const campaigns = $input.all().map((item) => item.json);
const campaign = campaigns.find((row) => String(row.id) === '23823733646');
if (!campaign) throw new Error('No se encontró la campaña PMAX de Kinku (23823733646).');
const microsToCop = (value) => Number(value || 0) / 1000000;
const leads = Number(campaign.conversions || 0);
const investment = microsToCop(campaign.costMicros);
const dailyBudget = microsToCop(campaign.amountMicros);
const periodDaysElapsed = Number(base.periodDaysElapsed || 1);
const periodBudget = dailyBudget * periodDaysElapsed;
const kpi = Number(base.pmax?.kpi || 30);
const performance = kpi > 0 ? Number(((leads / kpi) * 100).toFixed(2)) : 0;
const cpa = leads > 0 ? Math.round(investment / leads) : 0;
return [{ json: {
  ...base,
  pmax: { ...base.pmax, kpi, leads, performance, budget: Number(periodBudget.toFixed(2)), investment: Number(investment.toFixed(2)), cpa },
  googleAds: {
    source: 'live', managerCustomerId: '6584892239', customerId: '9240696515',
    campaignId: String(campaign.id), campaignName: campaign.name,
    campaignType: campaign.advertisingChannelType, status: campaign.status,
    dateRange: 'THIS_MONTH', periodMode: base.periodMode,
    periodStartDate: base.periodStartDate, periodEndDate: base.periodEndDate,
    periodStart: base.periodStart, periodEnd: base.periodEnd,
    periodDaysElapsed, dailyBudget: Number(dailyBudget.toFixed(2)),
    periodBudget: Number(periodBudget.toFixed(2)), impressions: Number(campaign.impressions || 0),
    interactions: Number(campaign.interactions || 0), conversions: leads,
    investment: Number(investment.toFixed(2)), cpa,
    optimizationScore: Number(campaign.optimizationScore || 0)
  },
  dataSource: 'mixed',
  dataSources: { ...base.dataSources, googleAds: 'live', metaAds: 'live', crm: 'mock' }
} }];

const base = $('Recolectar Datos Simulados').first().json;
const insights = $('Consultar Insights Meta Kinku').first().json.data || [];
const budgets = $input.first().json.data || [];
const ids = {
  recognition: '120249557003280774',
  investors: '120238954925180774',
  housing: '120238960041500774',
  studio: '120247687053780774'
};
const byId = (rows, id) => rows.find((row) => String(row.campaign_id || row.id) === id);
const actionValue = (row, type) => Number((row.actions || []).find((action) => action.action_type === type)?.value || 0);
const metric = (key, actionType, withKpi = true) => {
  const insight = byId(insights, ids[key]);
  const campaign = byId(budgets, ids[key]);
  if (!insight) throw new Error(`Meta Ads no devolvió insights para ${key} (${ids[key]}).`);
  if (!campaign) throw new Error(`Meta Ads no devolvió presupuesto para ${key} (${ids[key]}).`);
  const actual = actionValue(insight, actionType);
  const investment = Number(insight.spend || 0);
  const dailyBudget = Number(campaign.daily_budget || 0);
  const budget = dailyBudget * Number(base.periodDaysElapsed || 1);
  const kpi = withKpi ? Number(base[key]?.kpi || 0) : null;
  return {
    campaignId: ids[key], campaignName: insight.campaign_name, objective: insight.objective,
    status: campaign.effective_status || campaign.status, actionType,
    periodStartDate: insight.date_start, periodEndDate: insight.date_stop,
    impressions: Number(insight.impressions || 0), reach: Number(insight.reach || 0),
    actual, leads: actionType === 'lead' ? actual : undefined,
    kpi, performance: kpi > 0 ? Number(((actual / kpi) * 100).toFixed(2)) : undefined,
    dailyBudget, budget, investment, cpa: actionType === 'lead' && actual > 0 ? Math.round(investment / actual) : undefined
  };
};
const recognitionLive = metric('recognition', 'post_engagement');
const investorsLive = metric('investors', 'lead');
const housingLive = metric('housing', 'lead');
const studioLive = metric('studio', 'lead', false);
const metaLeads = investorsLive.leads + housingLive.leads + studioLive.leads;
const metaInvestment = investorsLive.investment + housingLive.investment + studioLive.investment;
return [{ json: {
  ...base,
  recognition: { ...base.recognition, actual: recognitionLive.actual, performance: recognitionLive.performance, budget: recognitionLive.budget, investment: recognitionLive.investment },
  investors: { ...base.investors, leads: investorsLive.leads, performance: investorsLive.performance, budget: investorsLive.budget, investment: investorsLive.investment, cpa: investorsLive.cpa },
  housing: { ...base.housing, leads: housingLive.leads, performance: housingLive.performance, budget: housingLive.budget, investment: housingLive.investment, cpa: housingLive.cpa },
  studio: { ...base.studio, leads: studioLive.leads, budget: studioLive.budget, investment: studioLive.investment, cpa: studioLive.cpa },
  metaAds: { source: 'live', accountId: 'act_302924541795503', currency: 'COP', timezone: 'America/Bogota', periodMode: base.periodMode, periodStartDate: base.periodStartDate, periodEndDate: base.periodEndDate, totalLeads: metaLeads, leadCampaignInvestment: metaInvestment, campaigns: { recognition: recognitionLive, investors: investorsLive, housing: housingLive, studio: studioLive } },
  dataSource: 'mixed',
  dataSources: { googleAds: 'mock', metaAds: 'live', crm: 'mock' }
} }];
